export const _uiDictionary = ui;

export function useT() {
  const { prefs } = useUIPrefs();
  const lang = (prefs.uiLanguage || "es") as UILanguage;
  return useCallback((key: string) => ui[lang]?.[key] ?? ui.en[key] ?? key, [lang]);
}

export function useSection() {
  const { prefs } = useUIPrefs();
  const lang = (prefs.uiLanguage || "es") as UILanguage;
  return useCallback((name: string) => sections[lang]?.[name] ?? name, [lang]);
}

export function translateSection(name: string, lang: UILanguage): string {
  return sections[lang]?.[name] ?? name;
}

